const fs = require("node:fs");
const path = require("node:path");
const {
  withDangerousMod,
  withGradleProperties,
  withSettingsGradle,
} = require("expo/config-plugins");

/**
 * `android/` is gitignored and regenerated by `expo prebuild`, so anything set
 * directly in android/gradle.properties is lost on the next build. This plugin
 * reapplies the release-size settings on every prebuild.
 *
 * - reactNativeArchitectures: the default (arm64-v8a, armeabi-v7a, x86, x86_64)
 *   ships four copies of every native library in one universal APK. x86/x86_64
 *   are emulator-only and armeabi-v7a is 32-bit; arm64-v8a covers every current
 *   Android device and is the only ABI Google Play requires.
 * - enableMinifyInReleaseBuilds / enableShrinkResourcesInReleaseBuilds: both
 *   default to false in the RN template (see android/app/build.gradle), so
 *   release builds ship unminified dex and every unreferenced resource.
 */
const GRADLE_PROPERTIES = {
  reactNativeArchitectures: "arm64-v8a",
  "android.enableMinifyInReleaseBuilds": "true",
  "android.enableShrinkResourcesInReleaseBuilds": "true",
};

/**
 * Defensive keep rules for the libraries in this app that resolve classes
 * reflectively at runtime. Most ship consumer rules in their AAR, but R8 is
 * being turned on here without an on-device regression suite, so the reflective
 * entry points are pinned explicitly.
 */
const PROGUARD_RULES = `
# --- added by plugins/with-android-build-optimizations.js ---
# Expo modules are discovered and instantiated by reflection.
-keep class expo.modules.** { *; }
-keep class * extends expo.modules.core.BasePackage { *; }

# React Native TurboModules / codegen specs.
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.uimanager.** { *; }
-keep,includedescriptorclasses class com.facebook.react.bridge.** { *; }

# Nitro Modules (react-native-mmkv 4.x) resolves its HybridObjects via JNI.
-keep class com.margelo.nitro.** { *; }

# Reanimated 4 / worklets host objects.
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }

-dontwarn okhttp3.**
-dontwarn okio.**
# --- end ---
`;

const RULES_MARKER = "with-android-build-optimizations.js";

/**
 * Native modules resolve to `node_modules/.bun/<pkg>@<version>+<hash>/node_modules/<pkg>/`,
 * and AGP puts the CMake staging tree in `<module>/android/.cxx/...`. The deepest
 * generated path (the prefab CMake config, referenced un-normalised through
 * `arm64-v8a/../prefab/...`) lands at exactly 260 characters. ninja as bundled
 * with CMake 3.22.1 stats via the ANSI Win32 API, which is capped at 260
 * regardless of the LongPathsEnabled registry setting, so the stat fails, ninja
 * treats the phony edge as out of date, re-runs CMake, and loops until it gives
 * up with "manifest 'build.ninja' still dirty after 100 tries".
 *
 * Relocating the staging directory to a short path at the repo root removes ~90
 * characters and keeps every generated object path well inside the limit.
 */
const NATIVE_BUILD_GRADLE = `
// --- added by plugins/${RULES_MARKER} ---
// Keep CMake staging paths short enough for ninja's ANSI Win32 stat (260 char cap).
// Registered from settings.gradle via beforeProject/whenPluginAdded so it runs
// before each module evaluates its own android { externalNativeBuild } block;
// setting it from the root project is too late and AGP throws
// "It is too late to set buildStagingDirectory".
gradle.beforeProject { project ->
    project.plugins.whenPluginAdded { plugin ->
        def pluginName = plugin.getClass().getName()
        if (pluginName == "com.android.build.gradle.LibraryPlugin"
                || pluginName == "com.android.build.gradle.AppPlugin") {
            def stagingRoot = new File(settingsDir.parentFile.parentFile.parentFile, ".native-build")
            project.extensions.configure("android") { androidExt ->
                androidExt.externalNativeBuild.cmake.buildStagingDirectory =
                    new File(stagingRoot, project.name)
            }
        }
    }
}
// --- end ---
`;

function withShortNativeBuildPaths(config) {
  return withSettingsGradle(config, (cfg) => {
    if (!cfg.modResults.contents.includes(RULES_MARKER)) {
      cfg.modResults.contents += NATIVE_BUILD_GRADLE;
    }
    return cfg;
  });
}

function withReleaseGradleProperties(config) {
  return withGradleProperties(config, (cfg) => {
    for (const [key, value] of Object.entries(GRADLE_PROPERTIES)) {
      const existing = cfg.modResults.find((item) => item.type === "property" && item.key === key);
      if (existing) {
        existing.value = value;
      } else {
        cfg.modResults.push({ type: "property", key, value });
      }
    }
    return cfg;
  });
}

function withProguardRules(config) {
  return withDangerousMod(config, [
    "android",
    (cfg) => {
      const rulesPath = path.join(cfg.modRequest.platformProjectRoot, "app", "proguard-rules.pro");
      const current = fs.existsSync(rulesPath) ? fs.readFileSync(rulesPath, "utf8") : "";
      if (!current.includes(RULES_MARKER)) {
        fs.writeFileSync(rulesPath, `${current}\n${PROGUARD_RULES}`, "utf8");
      }
      return cfg;
    },
  ]);
}

module.exports = function withAndroidBuildOptimizations(config) {
  return withProguardRules(withShortNativeBuildPaths(withReleaseGradleProperties(config)));
};
